UPDATE andrade_portal.settings SET data='{"homeServicesTitle":"Soluciones para lo que importa.","homeProcessTitle":"De la primera pregunta al siguiente paso.","homeProcessDescription":"Una atención clara, con información que puedes consultar cuando la necesites.","homeStep1Title":"Cuéntanos tu situación","homeStep1Text":"Envía una consulta o solicita un horario. Puedes hacerlo desde el formulario o con Alma; recibirás una referencia privada.","homeStep2Title":"Definimos cómo avanzar","homeStep2Text":"El abogado revisa tu solicitud y acuerda contigo el alcance de la atención. Si eliges una cita virtual, primero se verifica la transferencia.","homeStep3Title":"Tu atención, conectada","homeStep3Text":"Consulta la confirmación, la dirección o el enlace de videollamada en tu seguimiento. Las decisiones importantes también se comunican por correo.","homeApproachTitle":"Escuchar primero. Construir una estrategia contigo.","homeApproachText":"Detrás de cada consulta hay una persona y una decisión importante. La atención empieza por comprender tu situación, revisar los antecedentes y explicarte las alternativas con claridad.","homeModalitiesTitle":"Cerca de ti, estés donde estés.","homeOfficeText":"Conversemos personalmente en el despacho. Solicita un horario y espera la confirmación antes de acudir.","homeVirtualText":"Recibe atención por videollamada. El despacho confirma el pago y el horario antes de compartir el acceso a tu cita.","homeFaqTitle":"Antes de dar el primer paso.","homeFaq1Question":"¿Enviar una solicitud confirma mi cita?","homeFaq1Answer":"La solicitud inicia la revisión. Tu cita queda agendada cuando el despacho la confirma; puedes comprobarlo con tu enlace privado de seguimiento.","homeFaq2Question":"¿Qué debo preparar para la consulta?","homeFaq2Answer":"Un resumen de los hechos, las fechas relevantes y las preguntas que deseas resolver. El abogado te indicará qué documentos necesita revisar.","homeFaq3Question":"¿Cómo recibo las novedades?","homeFaq3Answer":"Conserva tu referencia y el enlace privado. El seguimiento reúne el estado actual; el correo comunica la recepción y las decisiones importantes. También puedes contactar al despacho por WhatsApp.","emailPolicy":"important"}'::jsonb || data WHERE id=true;
UPDATE andrade_portal.content SET data=jsonb_set(data,'{cover}','"/images/servicio-civil.webp"'),updated_at=now() WHERE kind='services' AND id='civil-patrimonial' AND COALESCE(data->>'cover','')='';
